FIELDNAMES = ["id", "topic", "language", "user_gender", "expected_response_language", "user_query",
              "info_collected", "must_cover", "expected_statutes", "must_not_claim", "notes"]


def main():
    out = Path(__file__).resolve().parent / "golden_dataset.csv"
    with out.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=FIELDNAMES)
        w.writeheader()
        for i, row in enumerate(ROWS, 1):
            w.writerow({"id": i, **row})
    print(f"Wrote {len(ROWS)} rows to {out}")
    print("Language counts:", Counter(r["language"] for r in ROWS))


if __name__ == "__main__":
    main()
